P.transport["quest:1099"] = {
  hash = "1dc458",
  fullHash = "1dc458",
  text = "Goblins Win!. In Thousand Needles, a goblin race ticket pays off when the goblins come out ahead. A prize box comes back to whoever held the winning stub. The goblin race ticket is the stub that counts when the goblins win. Hold on to it, and a goblin prize box is yours once the result is in. The gnome ticket has a result of its own, for the other side of the race.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1099-46a124ba3c6a1f15558a/1-0000.mp3", duration = 22.9093878, start = 0},
  },
}
P.transport["quest:1174"] = {
  hash = "93feba",
  fullHash = "93feba",
  text = "Gnomes Win!. In Thousand Needles, a gnome race ticket pays off when the gnomes come out ahead. A prize box comes back to whoever held the winning stub. The gnome race ticket is the stub that counts when the gnomes win. Hold on to it, and a gnome prize box is yours once the result is in. The goblin ticket has a result of its own, for the other side of the race.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1174-e3abea2f5712711c089d/1-0000.mp3", duration = 22.282449, start = 0},
  },
}
P.transport["quest:1582"] = {
  hash = "c5f129",
  fullHash = "c5f129",
  text = "Moonglow Vest. Moonglow Vest is a trade training task offered by the night elf leatherworker Lotherias in Darnassus. Overwhelmed by the constant needs of young adventurers heading into the wilds of Kalimdor, she trades the knowledge of a specialized night elven tunic pattern in exchange for bulk shipments of embossed leather gear. In the sheltered boughs of Darnassus, tradesmen work tirelessly to outfit the swelling ranks of sentinels and aspiring wilderness scouts. As young night elves and allied wanderers venture forth beyond Teldrassil into a volatile Kalimdor, reliable armor is in fierce demand. Master leatherworkers like Lotherias bear the burden of keeping these frontiers supplied with sturdy hides. To ensure her apprentices possess both endurance and technical precision, Lotherias requires proof of their handiwork through multiple matched garments: embossed gloves, boots, and cloaks. Meeting this quota earns her trust, prompting her to impart the distinct night elven pattern for the Moonglow Vest—a garment favored for balancing supple protection with agile mobility.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1582-b23950c2ff0e049adc5b/1-0000.mp3", duration = 65.28, start = 0},
  },
}
P.transport["quest:3861"] = {
  hash = "396fc9",
  fullHash = "396fc9",
  text = "CLUCK!. CLUCK! is an unusual, secretive interaction that allows an adventurer to gain the trust of ordinary barnyard poultry. By mimicking chicken calls and providing the proper grain, travelers can receive a prize egg to hatch a feathered companion of their own. While most travelers pay little mind to the simple chickens wandering the farmsteads of Azeroth, these birds hold a surprisingly perceptive nature. If an adventurer stoops to mimic their gestures and clucking long enough, the chicken ceases its mindless pecking and regards the mortal with uncanny interest. In that brief moment of connection, the bird scratches letters in the dirt, hinting at its hunger and directing the curious toward the proper farmer who can feed it. Satisfying the bird's cryptic request requires acquiring Special Chicken Feed. In Westfall, the Saldean family keeps such grain on hand for their flock. Presenting this specialized feed and offering enthusiastic encouragement causes the bird to eagerly peck down the meal. In exchange, the chicken produces a warm, freshly laid egg that can be nurtured into a loyal companion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3861-52e79d2c237141997b08/1-0000.mp3", duration = 66.2204082, start = 0},
  },
}
P.transport["quest:4513"] = {
  hash = "b8f08e",
  fullHash = "b8f08e",
  text = "A Little Slime Goes a Long Way. Following his initial study of tainted specimens, the gnome researcher Laris Geardawdle seeks untainted ooze samples to understand how these strange creatures adapt to their environment. Having realized that oozes absorb the corrupted nature of places like Felwood, he sends adventurers to discover and gather pure, unpolluted specimens from across Kalimdor. Laris Geardawdle's preliminary experiments in Ironforge hit an immediate stumbling block: the oozes he previously examined were thoroughly polluted by the dark energies of Felwood. While this demonstrated that oozes absorb and reflect the traits of their surroundings, it left him without a control group. To understand the baseline nature of ooze life, he needs specimens untouched by demonic taint or urban filth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4513-47f0d3706b2ddce718f2/1-0000.mp3", duration = 44.9044898, start = 0},
  },
}
P.transport["quest:5502"] = {
  hash = "4129ed",
  fullHash = "4129ed",
  text = "A Warden of the Horde. A Warden of the Horde concludes Children's Week by returning Grunth to Orphan Matron Battlewail in Orgrimmar's Valley of Honor. After seeing the world with his guardian, the young orphan hopes to become a hero himself. After the adventures of Children's Week, Grunth thanks his guardian for showing him more than he ever dreamed he would see. Remembering his parents' advice to rise above hardship, he says he hopes to become a hero like the adventurer. His final request is to return home and tell the matron about their time together. Returning to the orphanage in the Valley of Honor, adventurers return their young charge back into the care of Orphan Matron Battlewail. Taking responsibility for the young is considered a profound duty in the new Horde, where war has left countless children without parents. Battlewail commends your compassion as the true measure of a hero of the Horde, and Grunth parts ways with a beloved pet to ensure you remember the bond forged during your travels.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5502-35bb7e5e3863d6910f13/1-0000.mp3", duration = 57.6, start = 0},
  },
}
P.transport["quest:6544"] = {
  hash = "320a27",
  fullHash = "320a27",
  text = "Torek's Assault. Torek's Assault is a direct Horde raid launched from the wilds of Ashenvale against the nearby night elf garrison at Silverwing Outpost. Led by the orc raider Torek under orders from Splintertree Post, the strike aims to crush local Sentinel resistance and slay their commander, Duriel Moonfire. It marks one of the most brazen, bloody skirmishes in the ongoing war for Ashenvale's borders. Ashenvale is locked in an escalating border war between the Horde lumber camps and the native night elves. Seeking to break the Alliance's defensive perimeter, Torek gathers a pack of Splintertree raiders just outside Silverwing Outpost. Rather than waiting for a counter-attack, Torek coordinates a head-on charge to shatter the outpost's defenses before the night elves can mount a reinforced campaign against Splintertree Post. Silverwing Outpost stands as a fortified woodland bastion garrisoned by vigilant Silverwing Sentinels and fierce elven warriors. Torek's primary target is their leader, Duriel Moonfire. Bringing down Duriel decapitates the local night elf military hierarchy in the area, allowing the raiders to report a bloody victory back to commander Ertog Ragetusk at Splintertree Post.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6544-584f3149ad9f0523f8cd/1-0000.mp3", duration = 74.5534694, start = 0},
  },
}
P.transport["quest:6623"] = {
  hash = "783228",
  fullHash = "783228",
  text = "Horde Trauma. Horde Trauma is a summons directing accomplished Horde medics to report to Hammerfall in the Arathi Highlands. Doctor Gregory Victor, the chief physician of the Horde's trauma division, is looking to recruit and evaluate skilled hands capable of saving lives under extreme pressure. Answering the call places a medic directly into the grim, high-stakes reality of front-line field surgery. In Orgrimmar's Valley of Spirits, the orc first aid trainer Arnok delivers word to proficient healers that they have caught the attention of Doctor Gregory Victor himself. Victor oversees Horde Trauma from the fortified outpost of Hammerfall, tucked away in the contested hills of the Arathi Highlands. Arnok views the summons not merely as an order, but as the pinnacle of professional advancement for any battlefield surgeon. Reaching Hammerfall reveals that the post is far from comfortable. Operating amidst constant skirmishes with Stromgarde's forces and local hostile factions, Victor is inundated with wounded grunts, raiders, and scouts. The chief physician wastes no time welcoming newcomers with pleasantries; instead, recruits are immediately ordered into their scrubs to prove their worth during brutal, fast-paced emergency triage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6623-c6c7c990b896f8eba9b0/1-0000.mp3", duration = 73.4302041, start = 0},
  },
}
P.transport["quest:6641"] = {
  hash = "2814f5",
  fullHash = "2814f5",
  text = "Vorsha the Lasher. Vorsha the Lasher is a violent hydra terrorizing the Horde's foothold at Zoram'gar Outpost along the coast of Ashenvale. Revering the creature's ferocity, the local naga maintain an offering brazier on an offshore island to honor her. By extinguishing this sacred flame, Horde champions provoke Vorsha and draw her ashore to end her predatory assaults. Zoram'gar Outpost sits on a tenuous strip of coast in northwestern Ashenvale, constantly besieged by hostile wildlife, night elves, and serpentine invaders. Among the most destructive threats prowling the Zoram Strand is Vorsha the Lasher, a gargantuan hydra known for brutal, unprovoked strikes against the outpost. The beast emerges from the surf to crush fortifications and butcher warriors before vanishing back into the deep tides. The nearby naga do not merely tolerate the ravenous hydra; they actively venerate her predatory malice. On a rocky outcrop off the strand, the serpentine fiends keep an offering brazier burning continuously in tribute to Vorsha. Muglash, an orc determined to end the constant harassment of the outpost, realized that defiling this ritual flame would bring the beast surging to the surface in a fury, allowing the defenders to lure her into an ambush rather than waiting for another surprise slaughter.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6641-b9dcab0c47da57fd5296/1-0000.mp3", duration = 81.5804082, start = 0},
  },
}
P.transport["quest:6962"] = {
  hash = "26b898",
  fullHash = "26b898",
  text = "Treats for Great-father Winter. Treats for Great-father Winter is a festive holiday request offered during the Feast of Winter Veil in Orgrimmar. The jolly figurehead seated at the Smokywood Pastures display finds himself exhausted after hearing holiday wishes and asks a helpful adventurer for fresh gingerbread cookies and milk. While Greatfather Winter embodies the mythical spirit of winter and abundance across Azeroth, the figure greeting visitors in the Valley of Strength is a hardworking performer employed by Smokywood Pastures. Sitting through long shifts listening to hopeful citizens talk about festive goodies tends to work up an appetite. Tired of simply talking about seasonal treats, the Greatfather gladly enlists passing travelers to satisfy his craving for warm baking and a cold beverage. Satisfying the Greatfather's request requires a touch of home cooking. Adventurers must acquire holiday spices sold directly by the goblin peddlers of Smokywood Pastures, forage small eggs from wild birds across the wilderness, and bake classic gingerbread cookies. Paired with a pitcher of ice cold milk purchased from a local tavern, the modest offering rewards the baker with festive cheer and a small token of gratitude from the feast's organizers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6962-22f76714769f49c28a86/1-0000.mp3", duration = 75.9902041, start = 0},
  },
}
P.transport["quest:7025"] = {
  hash = "1f0529",
  fullHash = "1f0529",
  text = "Treats for Greatfather Winter. During the Feast of Winter Veil, the performer portraying Greatfather Winter in Ironforge grows tired and asks passersby for a seasonal treat. Bringing him freshly baked gingerbread cookies and ice cold milk earns a festive reward and his warm gratitude. While Winter Veil has its roots in ancient titan lore and dwarven myths of an immortal figure cloaked in winter's chill, modern festivities rely heavily on the commercial sponsorship of Smokywood Pastures. Stationed by the holiday tree in the Commons of Ironforge, an ordinary dwarf spends grueling hours suited up as Greatfather Winter, fielding holiday wishes from citizens and eager children alike. After listening to requests for gifts all day, the resident Greatfather Winter inevitably develops a hearty appetite of his own. Rather than asking for something extravagant, he requests a simple comfort: five freshly baked gingerbread cookies made with holiday spices and an ice cold milk to wash them down. The trade offers a moment of relief to an exhausted festival worker and spreads goodwill throughout the snowy capital.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7025-fd9843f22dda7ad91ec0/1-0000.mp3", duration = 64.9665306, start = 0},
  },
}
P.transport["quest:743"] = {
  hash = "11daa7",
  fullHash = "11daa7",
  text = "Dangers of the Windfury. Dangers of the Windfury is a rite of martial readiness offered by Ruul Eagletalon in Bloodhoof Village. Young tauren and Horde adventurers are tasked with battling the savage Windfury harpies nesting in the southeastern cliffs of Mulgore. Hunting these feral predators serves as an essential test of skill and survival before journeying beyond the tribal homeland. In Bloodhoof Village, the veteran warrior Ruul Eagletalon observes all travelers who pass through the heart of Mulgore. For those coming of age or seeking to prove themselves ready for wider adventures, Ruul demands tangible proof of their combat instincts. Survival beyond the sheltered valleys of Mulgore requires poise against aggressive, cunning foes, and Ruul uses the land's fiercest native predators to measure a youth's mettle. The Windfury harpies roost along the mountainous southeastern rim of Mulgore, safely off the beaten trails but constantly posing a threat to wandering wildlife and isolated travelers. Vicious and relentlessly hungry for fresh flesh, these avian terrors rely on swift swoops and razor-sharp claws. Defeating them and claiming their talons demonstrates not only the power to defeat an entrenched threat, but the speed required to counter aerial raiders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_743-4f73393cbe8552168c68/1-0000.mp3", duration = 77.9232653, start = 0},
  },
}
P.transport["quest:7493"] = {
  hash = "949938",
  fullHash = "949938",
  text = "The Journey Has Just Begun. \"The Journey Has Just Begun\" is a Horde quest offered in Orgrimmar to skilled leatherworkers following the defeat of Onyxia. Overlord Runthak recognizes the hero's craft and imparts the rare technique required to fashion protective cloaks from the broodmother's scales. This vital craft prepares the Horde for the deadly flames of Blackrock Spire. The fall of Onyxia represents a triumph for the Horde, but it does not mark the end of the threat posed by the black dragonflight. The broodmother's scaled hide possesses remarkable resilience against draconic flame. Rather than letting such materials go to waste, Horde leadership seeks craftsmen capable of turning the dragon's remains into defensive armor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7493-816487bc15b39824aa65/1-0000.mp3", duration = 41.7697959, start = 0},
  },
}
P.transport["quest:7497"] = {
  hash = "d0ed86",
  fullHash = "d0ed86",
  text = "The Journey Has Just Begun. This quest represents the hard-earned recognition of a seasoned artisan following the defeat of Onyxia. Major Mattingly imparts the vital technique required to craft an Onyxia Scale Cloak, turning the fallen broodmother's remains into essential protection against her brother. While many champions can claim credit for bringing low the broodmother Onyxia, very few possess both martial prowess and the master leatherworking skill required to work her formidable hide. When a hero with such combined talents reports to Major Mattingly in Stormwind, the officer acknowledges how vital those crafting skills are for the battles yet to come.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7497-592e871f4bfec01ec900/1-0000.mp3", duration = 37.8514286, start = 0},
  },
}
P.transport["quest:768"] = {
  hash = "de1221",
  fullHash = "de1221",
  text = "Gathering Leather. Gathering Leather is a straightforward trade request offered by Veren Tallstrider on the rises of Thunder Bluff. To sustain the capital and test young hunters, Veren exchanges a bundle of cured light leather skins for crafted goods. It highlights the deeply ingrained tauren tradition of turning the fruits of the plains hunt into essential clothing and armor. In the newly settled capital atop the high mesas of Mulgore, craftsmanship and survival walk hand in hand. Veren Tallstrider works skins into clothing and protective armor needed by the growing population of Thunder Bluff. Rather than harvesting everything himself, he encourages young adventurers heading out into the plains to bring back their quarry, turning mundane hunting into honorable civic service. For the tauren, hunting beasts across the grasslands is not sport; it is an honorable endeavor that feeds, clothes, and shelters the tribe. Veren Tallstrider looks for hunters with a hunger to bring honor to their clan, asking specifically for light leather stripped from the local wildlife. In return for twelve well-kept hides, he repays the hunter with sturdy goods, reinforcing the mutual support that binds tauren society together.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_768-1c410b448bb3103b6b69/1-0000.mp3", duration = 73.6391837, start = 0},
  },
}
P.transport["quest:769"] = {
  hash = "471691",
  fullHash = "471691",
  text = "Kodo Hide Bag. Kodo Hide Bag is a trade quest offered by Veren Tallstrider, a skilled tauren leatherworker atop the high mesas of Thunder Bluff. In exchange for fundamental crafting supplies, he passes on the traditional plains technique for stitching durable travel packs from sturdy beast hide. It serves as an early rite of passage for apprentice leathercrafters in Mulgore. Perched on Thunder Bluff's crafting rises, Veren Tallstrider upholds the long-standing nomadic tradition of wasting nothing from the hunt. To earn his tutelage, an aspiring leatherworker must present him with cured light leather and sturdy thread. By demonstrating their competence with foundational materials, apprentices prove they are ready to craft goods worthy of carrying survival gear across Kalimdor's rugged expanses. To the tauren, the kodo beast is an emblem of endurance, strength, and steady resolve. Its thick hide shields against brambles, biting wind, and beast claws alike. Crafting bags and garments from kodo hide is not merely a utilitarian act, but an expression of reverence for the animal that has nourished and carried the Shu'halo through countless generations across the plains of Mulgore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_769-8ec338e29d6041149b99/1-0000.mp3", duration = 70.4783673, start = 0},
  },
}
P.transport["quest:770"] = {
  hash = "c6c442",
  fullHash = "c6c442",
  text = "The Demon Scarred Cloak. The Demon Scarred Cloak is a ragged pelt recovered from the legendary white wolf Ghost Howl, who roams the grassy plains of Mulgore. Marked by an enduring wound inflicted during past clashes with the Burning Legion, the pelt serves as proof of the beast's release from torment. Bringing it to the elders of Bloodhoof Village brings closure to the story of a tragic local legend. Ghost Howl is an elusive white wolf known across Mulgore for both his ferocity and his sorrowful howl. When slain, the beast leaves behind a pelt that is visibly scarred by foul demonic corruption. These lingering marks date back to the wolf's desperate battles against the invading demons of the Burning Legion, a confrontation that left Ghost Howl wounded in both flesh and spirit long after the Third War came to a close. The tauren of Mulgore maintain a deep respect for the wild beasts of their homeland, revering them as children of the Earth Mother. Presenting the scarred cloak to Skorn Whitecloud in Bloodhoof Village confirms the demise of the tormented predator. Skorn recognizes the immense skill required to track and defeat Ghost Howl, expressing the somber hope that in death, the wolf's tortured spirit has finally attained peace.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_770-52a5e9a60a308ec0bf4a/1-0000.mp3", duration = 75.8334694, start = 0},
  },
}
P.transport["quest:8354"] = {
  hash = "2721d4",
  fullHash = "2721d4",
  text = "Chicken Clucking for a Mint. During the festive season of Hallow's End, Innkeeper Norman of the Undercity offers a piece of candy to travelers helping an ailing child. To earn the Undercity Mint, adventurers must cast aside their dignity and flap about like a chicken. The Undercity is rarely known for laughter or warmth, built as it is beneath the ruins of Lordaeron by the liberated Forsaken. Yet when Hallow's End arrives, even the grim denizens of the Trade Quarter join in seasonal revelry. Innkeeper Norman holds onto a stash of Undercity Mints, designated for those collecting treats on behalf of young Spoops, a sick orphan in need of holiday cheer. Rather than surrendering the treat outright to seasoned adventurers, Norman demands a bit of humiliating spectacle. Believing that grown warriors and spellcasters ought to earn their confections, he refuses to part with the mint until the petitioner mimics a barnyard chicken right before his counter.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8354-a53d30d9f0115b718286/1-0000.mp3", duration = 52.6367347, start = 0},
  },
}
P.transport["quest:8359"] = {
  hash = "c09fbd",
  fullHash = "c09fbd",
  text = "Flexing for Nougat. During the festive autumn celebration of Hallow's End, Innkeeper Gryshka in Orgrimmar offers sweet seasonal confections to those willing to play along. To earn a piece of Orgrimmar Nougat for a bedridden child, champions of the Horde must swallow their warrior pride and show off their muscles on command. Hallow's End brings high spirits, pranks, and confection gathering to the bustling capitals of Azeroth. While adventuring heroes often face dragons and dark sorcery, the traditions of the autumn holiday require a much lighter touch. Innkeeper Gryshka, presiding over the common room of Orgrimmar's inn, is happy to share her supply of holiday sweets, but only if patrons adhere to the oldest rule of the season: perform a trick, or leave empty-handed. Taking amusement in whatever disguise or armor an adventurer arrives in, Gryshka demands a show of raw Orcish strength. Before parting with a single piece of Orgrimmar Nougat meant for young Spoops, she insists on seeing the mighty traveler strike a muscular pose. It is a lighthearted reminder that even the most feared combatants in the Horde can be made to entertain the common folk for candy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8359-3a7011d6a7dba175a06a/1-0000.mp3", duration = 69.5379592, start = 0},
  },
}
P.transport["quest:8642"] = {
  hash = "b5e435",
  fullHash = "b5e435",
  text = "Silvervein the Elder. Silvervein the Elder is an honored ancestral spirit who appears during the Lunar Festival atop the hills overlooking Thelsamar in Loch Modan. Travelers pay their respects to him to honor the ancient ties among Azeroth's elder peoples. In return for acknowledging his presence and heritage, he bestows his ancestral blessing. Perched on the rolling ridges above Thelsamar, Elder Silvervein stands as a quiet guardian and reminder of antiquity. As a figure honored during the Lunar Festival, he represents the enduring memories of bygone eras. Even as the surrounding lands of Loch Modan grapple with trogg invasions and local disputes, Silvervein watches peacefully from his overlook. The presence of spirits like Silvervein serves to bridge the divide between modern folk and ancient lineages. When adventurers seek him out, he expresses gratitude that travelers still pay homage to the olden races of Azeroth. His greeting carries the warmth of ancestral appreciation, offering a commemorative token to those who honor him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8642-da93964529710fa6efe0/1-0000.mp3", duration = 63.5036735, start = 0},
  },
}
P.transport["quest:8646"] = {
  hash = "c72ceb",
  fullHash = "c72ceb",
  text = "Hammershout the Elder. Elder Hammershout is an ancient spirit visited during the Lunar Festival, standing in the Park district of Stormwind. He rewards travelers who pause to honor his people and show reverence for the venerable heritage of Azeroth's elder races. His presence serves as a reminder of ancient bonds even in the heart of human territory. During the Lunar Festival, the spirits of revered ancestors manifest across Azeroth, offering wisdom and blessings to any traveler who takes time to pay their respects. Elder Hammershout appears in the Park district of Stormwind. Though he stands near the heart of modern human civilization, his appearance reminds passing adventurers of a time when the world was shaped by the ancient races who walked the land long before the kingdoms of today rose to prominence. Greeting Elder Hammershout requires neither martial trials nor perilous oaths, but rather a simple acknowledgment of the past. He expresses quiet relief and gratitude when the current inhabitants of the realm still take time to pay homage to the olden races. In exchange for this act of memory and respect, the Elder bestows a ceremonial token upon travelers, symbolizing the enduring communion between the living generation and the spirits who came before.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8646-88645850a39f48dcd724/1-0000.mp3", duration = 74.7102041, start = 0},
  },
}
P.transport["quest:8648"] = {
  hash = "733c15",
  fullHash = "733c15",
  text = "Darkcore the Elder. Darkcore the Elder is a seasonal quest encountered during the Lunar Festival within the Undercity. By seeking out Elder Darkcore, travelers pay homage to the ancient spirits honored across Azeroth and receive a Coin of Ancestry in return. During the Lunar Festival, spirits of ancient night elven and earthen ancestors appear throughout the continents to share their wisdom and blessings. Elder Darkcore resides in the shadowed halls of the Undercity, bearing witness to the modern realm while offering remembrance to those who seek out the roots of the world. Approaching Elder Darkcore satisfies an ancient custom of showing respect to the venerable dead and the timeless wardens of Azeroth. In recognition of this pilgrimage, the spirit gifts travelers a Coin of Ancestry as a token of goodwill and enduring memory.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8648-2141c09470ba70eda376/1-0000.mp3", duration = 48.64, start = 0},
  },
}
P.transport["quest:8649"] = {
  hash = "737a5b",
  fullHash = "737a5b",
  text = "Stormbrow the Elder. Elder Stormbrow is one of the ancient spirits honored during the Lunar Festival, standing by the water near Goldshire. Travelers who seek out this elder pay homage to the ancient traditions and the olden races of Azeroth. In return for showing respect, the elder bestows a small token of remembrance. Elder Stormbrow manifests near the tranquil pond tucked just behind the smithy in Goldshire. While the town usually bustles with armored guards, tradesfolk, and weary adventurers heading into the forest, the arrival of this honored spirit brings a quiet pause. Standing beneath the peaceful canopy of Elwynn Forest, Stormbrow welcomes anyone willing to honor the long history of the realm. The Lunar Festival marks a time when the spirits of great ancestors return to walk among the living. Elder Stormbrow commends mortal travelers for taking the time to remember those who came before. In exchange for acknowledging the wisdom and legacy of the elder peoples, he grants his blessing and a commemorative coin to celebrate the season.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8649-a6cc769e34f04fb62c17/1-0000.mp3", duration = 64.0783673, start = 0},
  },
}
P.transport["quest:8652"] = {
  hash = "62de07",
  fullHash = "62de07",
  text = "Graveborn the Elder. Graveborn the Elder is a Lunar Festival encounter situated near the town of Brill in Tirisfal Glades. During the celebration, travelers seek out Elder Graveborn among the blighted groves to honor the ancient forebears of Azeroth. Paying respects to this spirit earns his blessing and a token of the holiday. While the Forsaken dwell among ruined manors and grave sites in Tirisfal Glades, the Lunar Festival brings an unexpected communion with ancient times. Elder Graveborn appears as a spectral elder stationed just outside Brill. Even in a realm shattered by the Scourge and reclaimed by the undead, he welcomes pilgrims who pause to honor the ancient ways. The Lunar Festival marks a time when the great spirits of long-past eras return to offer wisdom and gratitude. When travelers approach Elder Graveborn, he remarks on how heartening it is that the inhabitants of Tirisfal still offer homage to the ancestors despite the land's current decay, bestowing a Coin of Ancestry upon those who greet him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8652-0cb606264e4b8dee34bd/1-0000.mp3", duration = 62.3804082, start = 0},
  },
}
P.transport["quest:8653"] = {
  hash = "9eb720",
  fullHash = "9eb720",
  text = "Goldwell the Elder. Goldwell the Elder is a Lunar Festival quest offered by Elder Goldwell in Kharanos, Dun Morogh. Honoring him reflects the enduring tradition of seeking out ancestral spirits across the snowbound dwarven lands. In exchange for your respects, he bestows a token of ancestral blessing. Standing in the bitter cold beside the Thunderbrew Distillery in Kharanos, Elder Goldwell watches over the bustling trade path leading to the gates of Ironforge. During the Lunar Festival, this venerable figure welcomes weary travelers, adventurers, and locals alike, embodying the long memory of ancient days when early mortals walked beneath the stars of Azeroth. Approaching Goldwell offers a moment of reflection amidst the harsh winter winds of Dun Morogh. He expresses relief and joy that mortals still remember the ancient races and their deeds, thanking all who pause their journeys to show respect. In turn, he awards a sacred Coin of Ancestry as an emblem of his blessing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8653-b07b39d03f8daef38331/1-0000.mp3", duration = 58.5404082, start = 0},
  },
}
P.transport["quest:8670"] = {
  hash = "e48676",
  fullHash = "e48676",
  text = "Runetotem the Elder. Runetotem the Elder is an encounter with an ancestral spirit during the Lunar Festival in Durotar. Found standing within Razor Hill under a pillar of heavenly light, she offers blessings and festival tokens to travelers who come to pay their respects to the past. During the Lunar Festival, the spirits of ancient elders materialize across Azeroth to commune with the living. Elder Runetotem manifests inside Razor Hill, positioned just past the southern entrance. Bathed in a clear beam of starlight from above, she watches over the orcish settlement and welcomes adventurers who step aside from their travels to acknowledge the wisdom of those who came before. Approaching Elder Runetotem does more than honor an individual ancestor. In exchange for your homage, she rewards you with a festival token of fortune and shares word of where other spirits may be found, pointing wanderers toward Elder Darkhorn and Elder High Mountain across the continent.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8670-65b506ca1a0b9538c7b4/1-0000.mp3", duration = 56.7902041, start = 0},
  },
}
P.transport["quest:8673"] = {
  hash = "7060f9",
  fullHash = "7060f9",
  text = "Bloodhoof the Elder. Bloodhoof the Elder is an encounter with one of the venerated ancestral spirits who manifests during the Lunar Festival. Located just outside Bloodhoof Village in Mulgore, this honored spirit acknowledges the respect paid by wandering travelers and grants an ancestral token in return. During the celebration of the Lunar Festival, the spirits of great heroes and elders from ages past return to Azeroth. Shrouded in celestial radiance, Elder Bloodhoof appears just north of Bloodhoof Village near the bridge. Approaching these venerated ancestors is an act of honoring past sacrifices, and in exchange, Elder Bloodhoof offers words of encouragement and a sacred Coin of Ancestry. Standing on the ancestral lands of Mulgore, Elder Bloodhoof serves as a bridge between the living tauren tribes and the memory of their forebears. For the tauren, honoring the dead is a pillar of spiritual life, reinforcing the harmony between the Earth Mother, the ancestors, and those currently walking the plains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8673-f559d4f363d9e9829b3f/1-0000.mp3", duration = 61.0220408, start = 0},
  },
}
P.transport["quest:8675"] = {
  hash = "4aa092",
  fullHash = "4aa092",
  text = "Skychaser the Elder. Elder Skychaser is an ancestral spirit who manifests during the Lunar Festival atop the Sentinel Tower in Westfall. Honoring her allows travelers across the dust-swept plains to pay homage to the wisdom of ages past. In return, the elder acknowledges the burning vigor of the living and grants her blessing. Amid the troubled scrublands of Westfall, Sentinel Hill stands as the lone fortified redoubt against Defias raiders and roving scavengers. During the Lunar Festival, an ancestral spirit named Elder Skychaser takes her place on the open platform atop the Sentinel Tower. High above the dust and wind, she keeps a patient vigil over the weary soldiers and beleaguered settlers below, welcoming anyone who makes the climb to show respect. The Lunar Festival marks a sacred season observed across Azeroth, celebrating wisdom, heritage, and the deeds of ancient spirits who walked the earth before the present struggles. When approached, Elder Skychaser recognizes the vital spark within the traveler, accepting their homage and bestowing a token of her favor as a gift of kinship between the living and the honored dead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8675-b706065f955a03febfc2/1-0000.mp3", duration = 67.5004082, start = 0},
  },
}
P.transport["quest:8677"] = {
  hash = "8cf262",
  fullHash = "8cf262",
  text = "Darkhorn the Elder. Darkhorn the Elder is a seasonal quest completed by seeking out Elder Darkhorn in Orgrimmar during the Lunar Festival. Travelers pay their respects to the honored ancestor, receiving a token of wisdom and celebration in return. She stands in the heart of the Horde capital as a testament to age, survival, and ancestral pride. During the Lunar Festival, the spirits of revered ancestors manifest across Azeroth to share their wisdom with the living. Elder Darkhorn rests within the fortified ramparts of Orgrimmar, observing the bustle of the young warrior city. Approaching her offers champions of the Horde—and any Alliance adventurer brave enough to slip through the gates—a chance to pay formal homage to those who walked the earth generations before. Upon receiving greeting and reverence from passing travelers, Elder Darkhorn acknowledges the vibrant spark of life within them. In exchange for honoring the ways of old, she grants a Coin of Ancestry and her personal blessing. These tokens celebrate the triumph over ancient perils and remind the living to cherish the strength passed down through unbroken bloodlines.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8677-81775403c1682166b2fb/1-0000.mp3", duration = 70.0865306, start = 0},
  },
}
P.transport["quest:8678"] = {
  hash = "579cb5",
  fullHash = "579cb5",
  text = "Proudhorn the Elder. Proudhorn the Elder is an ancestral tauren spirit honored during the Lunar Festival atop the heights of Thunder Bluff. Visiting him is an act of deep reverence, acknowledging the wisdom of the ancestors who watch over Mulgore and the Horde. Perched high on the windblown mesas of Thunder Bluff, Proudhorn the Elder manifests as an ancestral presence during the Lunar Festival. Tauren culture holds the voices of their ancestors in the highest regard, believing that the spirits of ancient leaders and sages linger to offer guidance and strength to the living. Travelers who climb the heights to pay their respects to Elder Proudhorn are greeted not as strangers, but as vital flames of life. In exchange for the traveler's homage, the elder bestows a Coin of Ancestry, symbolizing communion between the enduring past and the living champions fighting for the world's future.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8678-82facfcf39e1a79f4755/1-0000.mp3", duration = 51.9314286, start = 0},
  },
}
P.transport["quest:8680"] = {
  hash = "6f3ee9",
  fullHash = "6f3ee9",
  text = "Windtotem the Elder. Elder Windtotem is an honored ancestor spirit who appears on a bluff overlooking the goblin port of Ratchet during the Lunar Festival. Bathed in a radiant shaft of celestial light, she receives travelers seeking to honor the wisdom of ages past. Paying homage to her rewards mortals with an ancestral blessing and guidance toward other elders walking Kalimdor. Perched on a grassy hill just northwest of the flight master in Ratchet, Elder Windtotem looks out over the bustling goblin docks and the open sea. While the harbor beneath her trades in iron, gunpowder, and coin, the elder stands apart in quiet contemplation, touched only by the quiet winds of the Barrens and the celestial glow descending from above. Like the other ancestral spirits summoned forth during the Lunar Festival, Elder Windtotem acts as a guide to wandering mortals. Those who seek her out not only earn her blessing and a token of her favor, but also receive whispers detailing the whereabouts of neighboring elders throughout the continent, including Elder Runetotem and Elder Bloodhoof.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8680-4dea5814dcd74a37cc9c/1-0000.mp3", duration = 65.7502041, start = 0},
  },
}
P.transport["quest:8717"] = {
  hash = "db94ab",
  fullHash = "db94ab",
  text = "Moonwarden the Elder. Elder Moonwarden is an honored ancestral spirit visited during the Lunar Festival, standing under a celestial beam of light at the Crossroads in the Barrens. Speaking with him offers travelers ancient wisdom and guidance toward other elders scattered throughout the continent. Standing amidst the dusty thoroughfare of the Crossroads, Elder Moonwarden appears bathed in a radiant column of heavenly light. He represents the ancient spirits revered during the Lunar Festival, a time when mortals pause their conflicts to pay homage to the wisdom of past generations. Elder Moonwarden muses on the starry heavens and their ability to reveal earthly mysteries to those who look up in search of truth. In addition to bestowing his own ancestral blessings, he offers seekers direction toward fellow elders across Kalimdor, including Elder Bloodhoof, Elder High Mountain, Elder Morningdew, and Elder Runetotem.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8717-c37a97c977c9d4c99cfe/1-0000.mp3", duration = 53.2897959, start = 0},
  },
}
P.transport["quest:8718"] = {
  hash = "33856c",
  fullHash = "33856c",
  text = "Bladeswift the Elder. Elder Bladeswift is an ancestral spirit honored during the Lunar Festival within the night elven capital of Darnassus. Located in the Cenarion Enclave, this ancient figure offers travelers wisdom drawn from the starry heavens above. Seeking his blessing connects adventurers directly to the revered traditions of the Cenarion Circle and the night elven people. During the Lunar Festival, the spirits of revered ancestors manifest across Azeroth to share their wisdom and bestow blessings upon travelers. Bladeswift the Elder stands amidst the serene boughs of the Cenarion Enclave in Darnassus. Unlike modern residents preoccupied with the trials of the present, this spectral forebear looks upward to the cosmos, contemplating the mysteries woven into the night sky. Night elven culture has long revered the celestial bodies as reflections of Elune and the deeper secrets of existence. Bladeswift reminds those who approach him that the countless stars hold answers to worldly struggles, urging the wise and fortunate to gaze upward. By acknowledging his presence, adventurers receive a Coin of Ancestry and take part in a timeless ceremony bridging the mortal realm with the spirits of the past.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8718-d0e29a3d0c1991cda8ac/1-0000.mp3", duration = 71.7061224, start = 0},
  },
}
P.transport["quest:8721"] = {
  hash = "e57267",
  fullHash = "e57267",
  text = "Starweave the Elder. Starweave the Elder is a Lunar Festival quest encountered in Darkshore. Adventurers seek out Elder Starweave in the settlement of Auberdine to pay their respects to the ancestral spirits of Kalimdor. In exchange for honoring ancient traditions, she offers celestial wisdom and her blessing. During the Lunar Festival, spirits of venerated ancestors manifest across the continents of Azeroth, battened in pillars of radiant celestial radiance. Elder Starweave takes her place among the night elves of Auberdine, a critical harbor town situated along the mist-shrouded coast of Darkshore. Travelers honoring the festival make pilgrimage to her side, seeking the timeless guidance of ages past. Elder Starweave contemplates the cosmic tapestry above Kalimdor, reminding all who approach that the stars carry answers to mortal doubts and worldly riddles. Those who take the time to seek her council are urged to look skyward for truth and receive ancestral favor alongside tidings of other wandering spirits across the wild frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8721-50082244e453ae35db94/1-0000.mp3", duration = 64.3918367, start = 0},
  },
}
P.transport["quest:8725"] = {
  hash = "defe0e",
  fullHash = "defe0e",
  text = "Riversong the Elder. Elder Riversong is an ancestral night elf spirit honored during the Lunar Festival, found resting beneath a quiet shrine in Astranaar. Bathed in a beam of moonlight, she offers quiet wisdom to travelers and directs pilgrims toward other revered ancestors across the lands of Kalimdor. Amid the ancient boughs and wooden walkways of Astranaar, Elder Riversong appears under an open night elf shrine. Marked by a distinct column of celestial light piercing the Ashenvale canopy, her ethereal presence serves as a focal point for participants in the Lunar Festival seeking communion with past generations. Elder Riversong reminds pilgrims of the ancient night elven tradition of reading truth and mystery in the starry sky. Her words direct travelers to seek wisdom through patience and contemplation, guiding those honoring the season on toward fellow spirits, including Elder Starweave.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8725-c44a79c75230c55a9b26/1-0000.mp3", duration = 55.0661224, start = 0},
  },
}
P.transport["quest:8828"] = {
  hash = "eae137",
  fullHash = "eae137",
  text = "Winter's Presents. Winter's Presents is an invitation extended to adventurers in Orgrimmar during the Feast of Winter Veil. Guided by holiday organizers and goblin apparatus tenders, Horde heroes are directed to visit Great-father Winter beneath the decorated festive tree to claim gifts prepared for them. As the chill winds of late year sweep across Durotar, the Feast of Winter Veil brings a rare moment of peace and celebration to the harsh red stones of Orgrimmar. Promoters from Smokywood Pastures, alongside holiday enthusiasts, ensure that every warrior, hunter, and wanderer resting in the capital knows that gifts await them beneath the decorated tree. Seated amidst holiday ribbons and packaged cartons near the Smokywood Pastures market stands Great-father Winter himself. While the ancient figure embodies the renewal of the season, the savvy merchant goblins never miss an opportunity to remind visitors that the holiday spirit pairs exceptionally well with their stock of seasonal wares and festive treats.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8828-adc5dda91fff1fdc93ec/1-0000.mp3", duration = 60.395102, start = 0},
  },
}
P.transport["quest:8866"] = {
  hash = "8a8ae1",
  fullHash = "8a8ae1",
  text = "Bronzebeard the Elder. Bronzebeard the Elder is a Lunar Festival encounter with Elder Bronzebeard within the dwarven mountain city of Ironforge. Honoring him during this ancestral celebration rewards travelers with wisdom and a token of his esteem. It reflects the deep reverence the folk of Khaz Modan hold for their forebears and long-lived heritage. During the Lunar Festival, spirits and venerable elders manifest across Azeroth to share their wisdom with travelers honoring the past. In Ironforge, Elder Bronzebeard stands as an embodiment of the stalwart resilience of the Bronzebeard clan. When approached by adventurers seeking to pay their respects, he expresses quiet satisfaction that the people of this land still acknowledge and honor the lineage of the olden races. The encounter requires no great trial or perilous expedition, asking only that travelers pause, acknowledge the elder's presence, and offer greeting. In turn, Elder Bronzebeard extends his well wishes and bestows a Coin of Ancestry. These sacred festival tokens serve as physical reminders of the living connection between modern heroes and the generations who forged Khaz Modan from stone and fire.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8866-146a708f3cbe8d4d714b/1-0000.mp3", duration = 68.8065306, start = 0},
  },
}
P.transport["quest:98247"] = {
  hash = "85054a",
  fullHash = "85054a",
  text = "Shipping Label. The Shipping Label is a recovered freight marker attached to a supply crate owned by the Azeroth Commerce Authority. Directing couriers to their trade hub at the Three Corners crossroads in Redridge Mountains, it introduces travelers to the organization's network of independent haulers. Found pasted to a stocked supply crate, this damaged shipping label marks cargo belonging to the Azeroth Commerce Authority. Although the intended destination and recipient have been torn away, clear instructions direct anyone who discovers the freight to return it or report to the authority's trade outpost in the Redridge Mountains. Beside the formal text, a rudimentary map sketches out the roads leading toward the Three Corners intersection. At the crossroads of Three Corners, representatives of the Azeroth Commerce Authority actively enlist travelers as independent couriers. Rather than binding haulers to strict merchant contracts, the authority operates an informal network where adventurers are compensated with Merchant's Favor in return for recovering missing cargo and fulfilling abandoned deliveries along the highway.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98247-c07fd56cbcf4e06604e5/1-0000.mp3", duration = 66.6122449, start = 0},
  },
}
